import { characterStatsAt, type RefCharacter } from "@gml/core";
import data from "./generated/characters.generated.json";

/**
 * Raw Star Rail character data for research across levels: growth tables (one row per ascension) and every
 * skill's parameters at every skill level. Generated by scripts/build-hsr-presets.mjs together with the presets,
 * from the same snapshot (see `hsrCharacterSource`).
 */
export interface HsrCharacter extends RefCharacter {
  /** Name as shown in the presets (Trailblazer variants are told apart). */
  displayName: string;
}

interface Generated {
  source: { text: string; version: string };
  /** Level the presets are built at, and the skill level each skill type uses there. */
  presetLevel: number;
  presetSkillLevels: Record<string, number>;
  characters: HsrCharacter[];
}
const gen = data as unknown as Generated;

export const hsrCharacters: readonly HsrCharacter[] = gen.characters;
export const hsrCharacterSource: { text: string; version: string } = gen.source;
/** The presets (`@gml/data-hsr/presets`) are these characters at this level… */
export const HSR_PRESET_LEVEL: number = gen.presetLevel;
/** …with these skill levels (basic / skill / ultimate / talent), i.e. all traces unlocked, no eidolons. */
export const HSR_PRESET_SKILL_LEVELS: Readonly<Record<string, number>> = gen.presetSkillLevels;

const byId = new Map(gen.characters.map((c) => [c.id, c]));
export const findHsrCharacter = (id: string): HsrCharacter | undefined => byId.get(id);

/** Character id ("1003") of a preset id ("hsr-1003") or a unit id ("hsr_1003"); null for anything else. */
export function hsrCharacterIdOf(presetOrUnitId: string): string | null {
  return /^hsr[-_](\d+)/.exec(presetOrUnitId)?.[1] ?? null;
}

/** Base stats (no equipment) at a level; ascension defaults to the lowest one that reaches the level. */
export function hsrStatsAt(id: string, level: number, ascension?: number): Record<string, number> {
  const ch = byId.get(id);
  if (!ch) throw new Error(`unknown Star Rail character ${id}`);
  return ascension === undefined ? characterStatsAt(ch, level) : characterStatsAt(ch, level, ascension);
}

/** A skill's parameters at a skill level (clamped to 1…maxLevel), e.g. [multiplier, …]. */
export function hsrSkillParams(id: string, skillId: string, level: number): number[] {
  const sk = byId.get(id)?.skills.find((s) => s.id === skillId);
  if (!sk) throw new Error(`unknown skill ${skillId} of Star Rail character ${id}`);
  const l = Math.max(1, Math.min(sk.maxLevel, Math.round(level)));
  return [...(sk.params[l - 1] ?? [])];
}
